"""Reduced-rank linear native repair plus retained nonlinear GELU features.

All coefficients are direct projections of unlabeled calibration states. A
Schur complement removes the retained-feature component before one SVD gives
the reduced-rank linear map. GELU(x)-GELU(-x)=x implements that map exactly.
There are no gradients, optimizer iterations, or arithmetic-answer targets.
"""
import json,torch

def restore(host,layer,edited_text,host_raw,host_gelu,rows,columns,
            donor_count=560,rank=64,ridge=.001,ntrain=384*64):
    W=host[f'transformer.h.{layer}.mlp.c_proj.weight'].double();acts=edited_text['captures'][f'{layer}.gelu'].reshape(-1,3072).double();X=edited_text['captures'][f'{layer}.ln2'].reshape(-1,768).double();A=acts[:ntrain];mu=A.mean(0);cov=A.T@A/ntrain-mu[:,None]*mu[None,:]
    readout=host['transformer.wte.weight'].double()*host['transformer.ln_f.weight'].double();readout-=readout.mean(1,keepdim=True);common=host_raw.reshape(-1,768).double().mean(0)+host_gelu.reshape(-1,3072).double().mean(0)@W.T+host[f'transformer.h.{layer}.mlp.c_proj.bias'].double();common-=common.mean();common/=common.norm();readout-=(readout@common)[:,None]*common[None,:];metric=readout.T@readout/len(readout);del readout
    cost=(W*(metric@W)).sum(0).clamp_min(1e-12);scale=cost.sqrt();weighted=cov*scale[:,None]*scale[None,:];diag=weighted.diagonal().clone().clamp_min(0);L=torch.zeros(3072,donor_count,dtype=torch.float64);used=torch.zeros(3072,dtype=torch.bool);indices=[]
    for step in range(donor_count):
        pivot=int(diag.masked_fill(used,-1).argmax());indices.append(pivot);used[pivot]=True;col=weighted[:,pivot]-(L[:,:step]@L[pivot,:step] if step else 0);denom=max(float(col[pivot]),float(weighted.diagonal().max())*1e-15)**.5;L[:,step]=col/denom;diag=(diag-L[:,step].square()).clamp_min(0)
    donors=torch.tensor(indices);del weighted,L,diag
    Z=torch.cat((X,acts[:,donors]),1);meanZ=Z[:ntrain].mean(0);C=Z[:ntrain].T@Z[:ntrain]/ntrain-meanZ[:,None]*meanZ[None,:];Cza=Z[:ntrain].T@A/ntrain-meanZ[:,None]*mu[None,:];regular=C.clone();regular.diagonal().add_(ridge*C.diagonal().clamp_min(1e-8));reconstruct=torch.linalg.solve(regular,Cza);interceptA=mu-meanZ@reconstruct;error=acts[ntrain:]-Z[ntrain:]@reconstruct-interceptA;feature_cost=error.square().mean(0)*cost;feature_cost[donors]=torch.inf;selected=feature_cost.argsort()[:len(rows)+2*rank];del reconstruct,error,Cza,regular
    target=(host_raw.reshape(-1,768)-edited_text['captures'][f'{layer}.raw'].reshape(-1,768)).double();target+=(host_gelu.reshape(-1,3072).double()-acts)@W.T;target+=acts[:,selected]@W[:,selected].T;meanR=target[:ntrain].mean(0);cross=Z[:ntrain].T@target[:ntrain]/ntrain-meanZ[:,None]*meanR[None,:]
    Cxx=C[:768,:768];Cxd=C[:768,768:];Cdd=C[768:,768:].clone();Cdd.diagonal().add_(ridge*Cdd.diagonal().clamp_min(1e-8));D=torch.linalg.cholesky(Cdd);donor_to_x=torch.cholesky_solve(Cxd.T,D);donor_to_target=torch.cholesky_solve(cross[768:],D);conditional=Cxx-Cxd@donor_to_x;conditional=(conditional+conditional.T)/2;conditional.diagonal().add_(ridge*Cxx.diagonal().clamp_min(1e-8));cx=cross[:768]-Cxd@donor_to_target;chol=torch.linalg.cholesky(conditional);white=torch.linalg.solve_triangular(chol,cx,upper=False);U,s,Vh=torch.linalg.svd(white,full_matrices=False);left=torch.linalg.solve_triangular(chol.T,U[:,:rank]*s[:rank].sqrt()[None,:],upper=True);right=s[:rank].sqrt()[:,None]*Vh[:rank];linear=left@right;donor_repair=torch.cholesky_solve(cross[768:]-Cxd.T@linear,D);intercept=meanR-meanZ[:768]@linear-meanZ[768:]@donor_repair;residual=target-X@linear-acts[:,donors]@donor_repair-intercept;report={}
    for label,sl in (('construction',slice(0,ntrain)),('validation',slice(ntrain,None))):
        e=residual[sl];report[label]={'before_rms':float(target[sl].square().mean().sqrt()),'after_rms':float(e.square().mean().sqrt()),'weighted_after_rms':float(((e@metric)*e).sum(1).mean().clamp_min(0).sqrt()),'relative_squared_error':float(e.square().sum()/target[sl].square().sum())}
    factor_rms=((X[:ntrain]-meanZ[:768])@left).square().mean(0).sqrt().clamp_min(1e-6);linear_rows=left.T/factor_rms[:,None];linear_columns=right.T*factor_rms[None,:];both_rows=torch.stack((linear_rows,-linear_rows),1).reshape(2*rank,768);both_columns=torch.stack((linear_columns,-linear_columns),2).reshape(768,2*rank);combined_rows=torch.cat((rows,torch.cat((both_rows,torch.zeros(2*rank,1,dtype=torch.float64)),1)));combined_columns=torch.cat((columns,both_columns),1)
    fc=host[f'transformer.h.{layer}.mlp.c_fc.weight'].clone();fb=host[f'transformer.h.{layer}.mlp.c_fc.bias'].clone();fc[selected]=combined_rows[:,:768].float();fb[selected]=combined_rows[:,768].float();proj=W.clone();proj[:,donors]+=donor_repair.T;proj[:,selected]=combined_columns;bias=host[f'transformer.h.{layer}.mlp.c_proj.bias'].double()+intercept
    identity=torch.nn.functional.gelu(torch.nn.functional.linear(X[:2048].float(),both_rows.float())).double()@both_columns.T;identity_error=float((identity-X[:2048]@linear).abs().max());changed={f'transformer.h.{layer}.mlp.c_fc.weight':fc,f'transformer.h.{layer}.mlp.c_fc.bias':fb,f'transformer.h.{layer}.mlp.c_proj.weight':proj.float(),f'transformer.h.{layer}.mlp.c_proj.bias':bias.float()};maximum=max(float(v.abs().max()) for v in changed.values());assert maximum<=1e6 and all(bool(torch.isfinite(v).all()) for v in changed.values());trial={'rank':rank,'donors':donor_count,'ridge':ridge,'fit':report,'maximum_weight':maximum,'identity_max_float_error':identity_error,'selected_conditional_feature_cost':float(feature_cost[selected].sum()),'explained_linear_cross_energy':float(s[:rank].square().sum()/s.square().sum())};print('reduced-rank restoration',json.dumps(trial),flush=True)
    aux={'selected':selected[:len(rows)],'linear_selected':selected[len(rows):],'all_selected':selected,'donors':donors,'repair':donor_repair,'repair_intercept':intercept,'program_rows':rows,'program_columns':columns,'linear_rows':both_rows,'linear_columns':both_columns,'linear_map':linear,'text_repair_report':report,'capacity_ridge':ridge,'ridge_trials':[trial],'rank':rank,'metric_common_direction':common,'method':'closed-form conditional reduced-rank linear map plus retained GELU features'}
    return changed,aux
